  description = "GCP region"
}

variable "service_account_email" {
  type        = string
  description = "Service account email"
}

variable "environment" {
  type        = string
  description = "Environment (e.g., dev, prod)"
}

variable "owner" {
  type        = string
  description = "Owner of the resources"
}

resource "google_project_iam_binding" "service_account_token_creator" {
  project = var.project
  role    = "roles/iam.serviceAccountTokenCreator"
  members = [
    "serviceAccount:${var.service_account_email}",
  ]

  depends_on = [
    google_service_account.service_account,
  ]

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    environment = var.environment
    owner       = var.owner
  }
}

resource "google_project_iam_binding" "service_account_user" {
  project = var.project
  role    = "roles/iam.serviceAccountUser"
  members = [
    "serviceAccount:${var.service_account_email}",
  ]

  depends_on = [
    google_service_account.service_account,
  ]

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    environment = var.environment
    owner       = var.owner
  }
}

resource "google_service_account" "service_account" {
  account_id = "minimal-service-account"
  project    = var.project

  depends_on = [
    google_project_iam_binding.service_account_token_creator,
    google_project_iam_binding.service_account_user,
  ]

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    environment = var.environment
    owner       = var.owner
  }
}

provider "azurerm" {
  version = "3.34.0"
  features {}
}

variable "location" {
  type        = string
  description = "The location for the resources"
}

variable "resource_group_name" {
  type        = string
  description = "The name of the resource group"
}

variable "cosmos_account_name" {
  type        = string
  description = "The name of the Cosmos DB account"
}

variable "sql_database_name" {
  type        = string
  description = "The name of the SQL database"
}

variable "sql_container_name" {
  type        = string
  description = "The name of the SQL container"
}

variable "sql_container_partition_key_path" {
  type        = string
  description = "The partition key path for the SQL container"
}

variable "sql_container_throughput" {
  type        = number
  description = "The throughput for the SQL container"
}

variable "tags" {
  type        = map(string)
  description = "The tags for the resources"
}

resource "azurerm_resource_group" "example" {
  name     = var.resource_group_name
  location = var.location
  tags     = var.tags
}

resource "azurerm_cosmosdb_account" "example" {
  name                = var.cosmos_account_name
  resource_group_name = azurerm_resource_group.example.name
  location            = azurerm_resource_group.example.location
  offer_type          = "Standard"
  kind               = "GlobalDocumentDB"

  enable_automatic_failover = false

  consistency_policy {
    consistency_level = "Session"
  }

  geo_location {
    location          = azurerm_resource_group.example.location
    failover_priority = 0
  }

  tags = var.tags
}

resource "azurerm_cosmosdb_sql_database" "example" {
  name                = var.sql_database_name
  resource_group_name = azurerm_resource_group.example.name
  account_name        = azurerm_cosmosdb_account.example.name
  throughput          = 400
  tags                = var.tags
}

resource "azurerm_cosmosdb_sql_container" "example" {
  name                  = var.sql_container_name
  resource_group_name   = azurerm_resource_group.example.name
  account_name          = azurerm_cosmosdb_account.example.name
  database_name         = azurerm_cosmosdb_sql_database.example.name
  partition_key_path    = var.sql_container_partition_key_path
  partition_key_version = 1
  throughput            = var.sql_container_throughput
  unique_key {
    paths = ["/definition/idlong", "/definition/idshort"]
  }
  tags = var.tags
}

provider "google" {
  project = var.project_id
  region  = var.region
}

variable "project_id" {
  type        = string
  description = "The ID of the project"
}

variable "region" {
  type        = string
  description = "The region to deploy to"
}

variable "ssh_cidr" {
  type        = string
  description = "The CIDR to allow SSH from"
}

variable "dataflow_job_name" {
  type        = string
  description = "The name of the Dataflow job"
}

variable "staging_bucket_name" {
  type        = string
  description = "The name of the staging bucket"
}

variable "service_account_email" {
  type        = string
  description = "The email of the service account"
}

resource "google_storage_bucket" "staging" {
  name                        = var.staging_bucket_name
  location                    = var.region
  force_destroy               = true
  uniform_bucket_level_access = true
  versioning {
    enabled = true
  }
  encryption {
    default_kms_key_name = google_kms_key.staging.self_link
  }
  labels = {
    environment = "production"
  }
}

resource "google_kms_key_ring" "staging" {
  name     = "staging-keyring"
  location = var.region
  labels = {
    environment = "production"
  }
}

resource "google_kms_key" "staging" {
  name            = "staging-key"
  key_ring        = google_kms_key_ring.staging.self_link
  rotation_period = "100000s"
  labels = {
    environment = "production"
  }
}

resource "google_service_account" "dataflow" {
  account_id = "dataflow-sa"
  description = "Service account for Dataflow job"
  labels = {
    environment = "production"
  }
}

resource "google_service_account_key" "dataflow" {
  service_account_id = google_service_account.dataflow.id
  public_key_type    = "TYPE_X509_PEM_FILE"
  labels = {
    environment = "production"
  }
}

resource "google_iam_role" "dataflow" {
  name        = "dataflow-role"
  description = "Role for Dataflow job"
  permissions = [
    "dataflow.jobs.create",
    "dataflow.jobs.update",
    "dataflow.jobs.get",
    "dataflow.jobs.list",
    "dataflow.jobs.delete",
    "storage.buckets.get",
    "storage.objects.get",
    "storage.objects.list",
    "storage.objects.create",
    "storage.objects.update",
    "storage.objects.delete",
  ]
  labels = {
    environment = "production"
  }
}

resource "google_iam_policy" "dataflow" {
  name        = "dataflow-policy"
  description = "Policy for Dataflow job"
  policy_type = "CUSTOM"
  bindings {
    role = google_iam_role.dataflow.id
    members = [
      "serviceAccount:${google_service_account.dataflow.email}",
    ]
  }
  labels = {
    environment = "production"
  }
}

resource "google_iam_binding" "dataflow" {
  role = google_iam_role.dataflow.name
  members = [
    "serviceAccount:${google_service_account.dataflow.email}",
  ]
}

resource "google_dataflow_flex_template" "example" {
  provider           = google
  project             = var.project_id
  region              = var.region
  template_gcp_path   = "gs://${google_storage_bucket.staging.name}/template"
  container_spec_gcp_path = "gs://${google_storage_bucket.staging.name}/container-spec"
  service_account_email = google_service_account.dataflow.email
  labels = {
    environment = "production"
  }
}

resource "google_compute_firewall" "ssh" {
  name    = "ssh-firewall"
  network = "default"
  allow {
    protocol = "tcp"
    ports    = ["22"]
  }
  source_ranges = [var.ssh_cidr]
  target_tags = ["ssh"]
  labels = {
    environment = "production"
  }
}

provider "google" {
  project = var.project_id
  region  = var.region
}

variable "project_id" {
  type        = string
  sensitive   = true
  description = "The ID of the project"
}

variable "region" {
  type        = string
  description = "The region to create resources in"
}

variable "instance_id" {
  type        = string
  description = "The ID of the Spanner instance"
}

variable "database_id" {
  type        = string
  description = "The ID of the Spanner database"
}

variable "iam_members" {
  type        = list(string)
  description = "The list of IAM members to grant roles to"
}

