  name        = "sns-topic-role"
  description = "Role for SNS Topic"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Environment = var.environment
  }
}

