  description = "Project name"
}

variable "environment" {
  type        = string
  description = "Environment name"
}

variable "ssh_source_cidr" {
  type        = string
  description = "SSH source CIDR"
}

variable "aks_node_count" {
  type        = number
  description = "AKS node count"
}

variable "aks_node_vm_size" {
  type        = string
  description = "AKS node VM size"
}

variable "aks_node_pool_name" {
  type        = string
  description = "AKS node pool name"
}

variable "aks_cluster_name" {
  type        = string
  description = "AKS cluster name"
}

variable "resource_group_name" {
  type        = string
  description = "Resource group name"
}

variable "virtual_network_name" {
  type        = string
  description = "Virtual network name"
}

variable "subnet_name" {
  type        = string
  description = "Subnet name"
}

variable "subnet_address_prefix" {
  type        = string
  description = "Subnet address prefix"
}

variable "virtual_network_address_space" {
  type        = list(string)
  description = "Virtual network address space"
}

resource "azurerm_resource_group" "example" {
  name     = var.resource_group_name
  location = var.region
  tags = {
    Environment = var.environment
    Project     = var.project
  }
}

resource "azurerm_virtual_network" "example" {
  name                = var.virtual_network_name
  address_space       = var.virtual_network_address_space
  location            = azurerm_resource_group.example.location
  resource_group_name = azurerm_resource_group.example.name
  tags = {
    Environment = var.environment
    Project     = var.project
  }
}

resource "azurerm_subnet" "example" {
  name                 = var.subnet_name
  resource_group_name = azurerm_resource_group.example.name
  virtual_network_name = azurerm_virtual_network.example.name
  address_prefixes     = [var.subnet_address_prefix]
  tags = {
    Environment = var.environment
    Project     = var.project
  }
}

resource "azurerm_kubernetes_cluster" "example" {
  name                = var.aks_cluster_name
  location            = azurerm_resource_group.example.location
  resource_group_name = azurerm_resource_group.example.name
  dns_prefix          = var.aks_cluster_name
  kubernetes_version = "1.23.8"

  network_profile {
    network_plugin    = "azure"
    load_balancer_sku = "standard"
  }

  identity {
    type = "SystemAssigned"
  }

  tags = {
    Environment = var.environment
    Project     = var.project
  }
}

resource "azurerm_kubernetes_cluster_node_pool" "example" {
  name                  = var.aks_node_pool_name
  kubernetes_cluster_id = azurerm_kubernetes_cluster.example.id
  vm_size               = var.aks_node_vm_size
  node_count            = var.aks_node_count
  os_disk_size_gb       = 30
  os_type               = "Linux"
  vnet_subnet_id        = azurerm_subnet.example.id

  node_labels = {
    Environment = var.environment
    Project     = var.project
  }

  tags = {
    Environment = var.environment
    Project     = var.project
  }
}

resource "azurerm_network_security_group" "example" {
  name                = "example-nsg"
  location            = azurerm_resource_group.example.location
  resource_group_name = azurerm_resource_group.example.name

  security_rule {
    name                       = "SSH"
    priority                   = 100
    direction                  = "Inbound"
    access                     = "Allow"
    protocol                   = "Tcp"
    source_port_range          = "*"
    destination_port_range     = "22"
    source_address_prefix      = var.ssh_source_cidr
    destination_address_prefix = "*"
  }

  tags = {
    Environment = var.environment
    Project     = var.project
  }
}

resource "azurerm_network_security_group_association" "example" {
  network_security_group_id = azurerm_network_security_group.example.id
  subnet_id                 = azurerm_subnet.example.id
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS Region"
}

variable "sns_topic_name" {
  type        = string
  description = "SNS Topic Name"
}

variable "email_subscription_address" {
  type        = string
  description = "Email Subscription Address"
}

variable "environment" {
  type        = string
  description = "Environment"
}

resource "aws_sns_topic" "this" {
  name = var.sns_topic_name

  tags = {
    Environment = var.environment
    Name        = var.sns_topic_name
  }
}

resource "aws_sns_topic_subscription" "this" {
  topic_arn = aws_sns_topic.this.arn
  protocol  = "email"
  endpoint  = var.email_subscription_address
}

resource "aws_iam_policy" "sns_topic_policy" {
  name        = "${var.sns_topic_name}-policy"
  description = "Policy for SNS Topic"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sns:Publish"
        Resource = aws_sns_topic.this.arn
        Principal = {
          Service = "sns.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Environment = var.environment
    Name        = var.sns_topic_name
  }
}

resource "aws_iam_role" "sns_topic_role" {
  name        = "${var.sns_topic_name}-role"
  description = "Role for SNS Topic"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "sns.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Environment = var.environment
    Name        = var.sns_topic_name
  }
}

resource "aws_iam_role_policy_attachment" "sns_topic_policy_attachment" {
  role       = aws_iam_role.sns_topic_role.name
  policy_arn = aws_iam_policy.sns_topic_policy.arn
}

provider "azurerm" {
  version = "3.34.0"
  features {}
}

variable "region" {
  type        = string
  description = "Azure region"
}

variable "project" {
  type        = string
  description = "Project name"
}

variable "environment" {
  type        = string
  description = "Environment name"
}

variable "ssh_source_cidr" {
  type        = string
  description = "SSH source CIDR"
}

variable "admin_username" {
  type        = string
  description = "Admin username"
}

variable "admin_password" {
  type        = string
  sensitive   = true
  description = "Admin password"
}

resource "azurerm_resource_group" "example" {
  name     = "${var.project}-${var.environment}-rg"
  location = var.region
  tags = {
    environment = var.environment
    project     = var.project
  }
}

resource "azurerm_virtual_network" "example" {
  name                = "${var.project}-${var.environment}-vnet"
  address_space       = ["10.0.0.0/16"]
  location            = azurerm_resource_group.example.location
  resource_group_name = azurerm_resource_group.example.name
  tags = {
    environment = var.environment
    project     = var.project
  }
}

resource "azurerm_subnet" "example" {
  name                 = "${var.project}-${var.environment}-subnet"
  resource_group_name = azurerm_resource_group.example.name
  virtual_network_name = azurerm_virtual_network.example.name
  address_prefixes     = ["10.0.1.0/24"]
}

resource "azurerm_public_ip" "example" {
  name                = "${var.project}-${var.environment}-pip"
  location            = azurerm_resource_group.example.location
  resource_group_name = azurerm_resource_group.example.name
  allocation_method   = "Static"
  sku                 = "Standard"
  tags = {
    environment = var.environment
    project     = var.project
  }
}

resource "azurerm_application_gateway" "example" {
  name                = "${var.project}-${var.environment}-agw"
  location            = azurerm_resource_group.example.location
  resource_group_name = azurerm_resource_group.example.name
  sku {
    name = "Standard_v2"
    tier = "Standard_v2"
  }
  min_capacity = 1
  max_capacity = 10
  tags = {
    environment = var.environment
    project     = var.project
  }
  ssl_policy {
    policy_type = "Predefined"
    policy_name = "TLS_1_2"
  }
  ssl_certificate {
    name = "example-cert"
    data = file("~/.ssh/example-cert.pfx")
    password = var.admin_password
  }
  frontend_ip_configuration {
    name                 = "${var.project}-${var.environment}-feip"
    public_ip_address_id = azurerm_public_ip.example.id
  }
  frontend_port {
    name = "${var.project}-${var.environment}-feport"
    port = 443
  }
  backend_address_pool {
    name = "${var.project}-${var.environment}-beap"
  }
  backend_http_settings {
    name                  = "${var.project}-${var.environment}-behs"
    cookie_based_affinity = "Disabled"
    port                  = 443
    protocol              = "Https"
    request_timeout       = 60
  }
  http_listener {
    name                           = "${var.project}-${var.environment}-httpl"
    frontend_ip_configuration_name = azurerm_application_gateway.example.frontend_ip_configuration[0].name
    frontend_port_name             = azurerm_application_gateway.example.frontend_port[0].name
    protocol                       = "Https"
    ssl_certificate_name           = azurerm_application_gateway.example.ssl_certificate[0].name
    host_names                     = ["example.com"]
  }
  request_routing_rule {
    name                       = "${var.project}-${var.environment}-r3"
    rule_type                  = "Basic"
    http_listener_name         = azurerm_application_gateway.example.http_listener[0].name
    backend_address_pool_name  = azurerm_application_gateway.example.backend_address_pool[0].name
    backend_http_settings_name = azurerm_application_gateway.example.backend_http_settings[0].name
  }
  depends_on = [
    azurerm_public_ip.example,
    azurerm_virtual_network.example,
    azurerm_subnet.example
  ]
}

resource "azurerm_network_security_group" "example" {
  name                = "${var.project}-${var.environment}-nsg"
  location            = azurerm_resource_group.example.location
  resource_group_name = azurerm_resource_group.example.name
  tags = {
    environment = var.environment
    project     = var.project
  }
  security_rule {
    name                       = "SSH"
    priority                   = 100
    direction                  = "Inbound"
    access                     = "Allow"
    protocol                   = "Tcp"
    source_port_range          = "22"
    destination_port_range     = "22"
    source_address_prefix      = var.ssh_source_cidr
    destination_address_prefix = azurerm_subnet.example.address_prefixes[0]
  }
}

resource "azurerm_network_security_rule" "example" {
  name                        = "HTTPS"
  priority                    = 101
  direction                   = "Inbound"
  access                      = "Allow"
  protocol                    = "Tcp"
  source_port_range          = "*"
  destination_port_range      = "443"
  source_address_prefix      = var.ssh_source_cidr
  destination_address_prefix = azurerm_subnet.example.address_prefixes[0]
  resource_group_name         = azurerm_resource_group.example.name
  network_security_group_name = azurerm_network_security_group.example.name
}

resource "azurerm_subnet_network_security_group_association" "example" {
  subnet_id                 = azurerm_subnet.example.id
  network_security_group_id = azurerm_network_security_group.example.id
}

provider "google" {
  project = var.project_id
  region  = var.region
}

variable "project_id" {
  type        = string
  description = "The ID of the project"
}

variable "region" {
  type        = string
  description = "The region to deploy to"
}

variable "ssh_source_cidr" {
  type        = string
  description = "The CIDR to allow SSH access from"
}

variable "dataflow_job_name" {
  type        = string
  description = "The name of the Dataflow job"
}

variable "staging_bucket_name" {
  type        = string
  description = "The name of the staging bucket"
}

variable "service_account_email" {
  type        = string
  description = "The email of the service account"
}

resource "google_storage_bucket" "staging_bucket" {
  name                        = var.staging_bucket_name
  location                    = var.region
  force_destroy               = true
  uniform_bucket_level_access = true
  versioning {
    enabled = true
  }
  encryption {
    default_kms_key_name = google_kms_key.dataflow_key.id
  }
  labels = {
    environment = "dataflow"
  }
}

resource "google_kms_key" "dataflow_key" {
  name            = "dataflow-key"
  location        = var.region
  key_ring        = google_kms_key_ring.dataflow_key_ring.id
  rotation_period = "100000s"
  labels = {
    environment = "dataflow"
  }
}

resource "google_kms_key_ring" "dataflow_key_ring" {
  name     = "dataflow-key-ring"
  location = var.region
  labels = {
    environment = "dataflow"
  }
}

resource "google_service_account" "dataflow_service_account" {
  account_id = "dataflow-service-account"
  description = "Service account for Dataflow job"
  labels = {
    environment = "dataflow"
  }
}

resource "google_service_account_key" "dataflow_service_account_key" {
  service_account_id = google_service_account.dataflow_service_account.id
}

resource "google_iam_role" "dataflow_role" {
  name        = "dataflow-role"
  description = "Role for Dataflow job"
  permissions = [
    "dataflow.jobs.create",
    "dataflow.jobs.get",
    "dataflow.jobs.update",
    "dataflow.jobs.delete",
    "storage.buckets.get",
    "storage.objects.get",
    "storage.objects.create",
    "storage.objects.delete",
  ]
  labels = {
    environment = "dataflow"
  }
}

resource "google_iam_policy" "dataflow_policy" {
  name        = "dataflow-policy"
  description = "Policy for Dataflow job"
  policy_data = data.google_iam_policy.dataflow_policy.data
  labels = {
    environment = "dataflow"
  }
}

data "google_iam_policy" "dataflow_policy" {
  binding {
    role = google_iam_role.dataflow_role.id
    members = [
      "serviceAccount:${google_service_account.dataflow_service_account.email}",
    ]
  }
}

resource "google_iam_role_assignment" "dataflow_role_assignment" {
  role       = google_iam_role.dataflow_role.id
  members    = ["serviceAccount:${google_service_account.dataflow_service_account.email}"]
  condition {
    title       = "dataflow-condition"
    description = "Condition for Dataflow job"
    expression  = "request.time < timestamp('2025-01-01T00:00:00.000Z')"
  }
  labels = {
    environment = "dataflow"
  }
}

resource "google_dataflow_flex_template_run" "dataflow_job" {
  provider           = google
  name               = var.dataflow_job_name
  template_gcs_path  = "gs://${google_storage_bucket.staging_bucket.name}/template"
  parameters         = {
    "input" = "gs://${google_storage_bucket.staging_bucket.name}/input"
    "output" = "gs://${google_storage_bucket.staging_bucket.name}/output"
  }
  service_account_email = google_service_account.dataflow_service_account.email
  labels = {
    environment = "dataflow"
  }
}

resource "google_compute_firewall" "ssh_firewall" {
  name    = "ssh-firewall"
  network = "default"
  allow {
    protocol = "tcp"
    ports    = ["22"]
  }
  source_ranges = [var.ssh_source_cidr]
  target_tags   = ["dataflow"]
  labels = {
    environment = "dataflow"
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type        = string
  description = "AWS Region"
}

variable "project" {
  type        = string
  description = "Project Name"
}

variable "environment" {
  type        = string
  description = "Environment Name"
}

variable "cluster_name" {
  type        = string
  description = "EKS Cluster Name"
}

variable "subnet_ids" {
  type        = list(string)
  description = "List of Subnet IDs"
}

variable "node_group_name" {
  type        = string
  description = "EKS Node Group Name"
}

variable "instance_type" {
  type        = string
  description = "EC2 Instance Type"
}

variable "ssh_cidr" {
  type        = string
  description = "SSH Allowed CIDR"
}

variable "eks_version" {
  type        = string
  description = "EKS Version"
}

variable "node_group_instance_type" {
  type        = string
  description = "EKS Node Group Instance Type"
}

variable "node_group_desired_size" {
  type        = number
  description = "EKS Node Group Desired Size"
}

variable "node_group_max_size" {
  type        = number
  description = "EKS Node Group Max Size"
}

variable "node_group_min_size" {
  type        = number
  description = "EKS Node Group Min Size"
}

resource "aws_iam_role" "eks_node" {
  name        = "${var.project}-${var.environment}-eks-node"
  description = "EKS Node IAM Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Name        = "${var.project}-${var.environment}-eks-node"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_iam_role_policy_attachment" "eks_node_AmazonEKSWorkerNodePolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "eks_node_AmazonEC2ContainerRegistryReadOnly" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "eks_node_AmazonEKS_CNI_Policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.eks_node.name
}

resource "aws_eks_node_group" "this" {
  cluster_name    = var.cluster_name
  node_group_name = var.node_group_name
  node_role_arn   = aws_iam_role.eks_node.arn
  subnet_ids      = var.subnet_ids

  instance_types = [var.node_group_instance_type]

  scaling_config {
    desired_size = var.node_group_desired_size
    max_size     = var.node_group_max_size
    min_size     = var.node_group_min_size
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_node_AmazonEKSWorkerNodePolicy,
    aws_iam_role_policy_attachment.eks_node_AmazonEC2ContainerRegistryReadOnly,
    aws_iam_role_policy_attachment.eks_node_AmazonEKS_CNI_Policy,
  ]

  tags = {
    Name        = "${var.project}-${var.environment}-eks-node-group"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_security_group" "eks_node" {
  name        = "${var.project}-${var.environment}-eks-node"
  description = "EKS Node Security Group"
  vpc_id      = aws_subnet.this.vpc_id

  ingress {
    description = "SSH"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.ssh_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "${var.project}-${var.environment}-eks-node"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_subnet" "this" {
  cidr_block = "10.0.1.0/24"
  vpc_id     = aws_vpc.this.id
  availability_zone = "us-west-2a"

  tags = {
    Name        = "${var.project}-${var.environment}-subnet"
    Environment = var.environment
    Project     = var.project
  }
}

resource "aws_vpc" "this" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name        = "${var.project}-${var.environment}-vpc"
    Environment = var.environment
    Project     = var.project
  }
}

provider "google" {
  project = var.project_id
  region  = var.region
}

variable "project_id" {
  type        = string
  description = "The ID of the project"
}

variable "region" {
  type        = string
  description = "The region to deploy to"
}

variable "ssh_source_cidr" {
  type        = string
  description = "The source CIDR for SSH access"
}

variable "vpc_name" {
  type        = string
  description = "The name of the VPC"
}

variable "subnet_name" {
  type        = string
  description = "The name of the subnet"
}

variable "subnet_cidr" {
  type        = string
  description = "The CIDR of the subnet"
}

variable "cloud_router_name" {
  type        = string
  description = "The name of the Cloud Router"
}

variable "bgp_asn" {
  type        = number
  description = "The BGP ASN for the Cloud Router"
}

resource "google_compute_network" "vpc" {
  name                    = var.vpc_name
  auto_create_subnetworks = false
  mtu                     = 1460
  routing_mode            = "REGIONAL"

  tags = {
    environment = "production"
  }
}

resource "google_compute_subnetwork" "subnet" {
  name          = var.subnet_name
  ip_cidr_range = var.subnet_cidr
  region        = var.region
  network       = google_compute_network.vpc.id

  tags = {
    environment = "production"
  }
}

resource "google_compute_firewall" "ssh" {
  name    = "ssh-firewall"
  network = google_compute_network.vpc.id

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }

  source_ranges = [var.ssh_source_cidr]

  target_tags = ["ssh-access"]

  tags = {
    environment = "production"
  }
}

resource "google_compute_firewall" "icmp" {
  name    = "icmp-firewall"
  network = google_compute_network.vpc.id

  allow {
    protocol = "icmp"
  }

  source_ranges = [var.ssh_source_cidr]

  target_tags = ["icmp-access"]

  tags = {
    environment = "production"
  }
}

resource "google_compute_firewall" "https" {
  name    = "https-firewall"
  network = google_compute_network.vpc.id

  allow {
    protocol = "tcp"
    ports    = ["443"]
  }

  source_ranges = ["0.0.0.0/0"]

  target_tags = ["https-access"]

  tags = {
    environment = "production"
  }
}

resource "google_compute_router" "router" {
  name    = var.cloud_router_name
  region  = var.region
  network = google_compute_network.vpc.id

  bgp {
    asn = var.bgp_asn
  }

  tags = {
    environment = "production"
  }
}

# Configure the AWS Provider
provider "aws" {
  region = var.aws_region
}

# Configure the Azure Provider
provider "azurerm" {
  features {}
  subscription_id = var.azure_subscription_id
  client_id      = var.azure_client_id
  client_secret = var.azure_client_secret
  tenant_id      = var.azure_tenant_id
}

# Configure the GCP Provider
provider "google" {
  project = var.gcp_project
  region  = var.gcp_region
}

# Create a random password for the database
resource "random_password" "db_password" {
  length = 16
  special = true
}

# AWS RDS
resource "aws_db_instance" "example" {
  allocated_storage    = 20
  engine               = "postgres"
  engine_version       = "13.4"
  instance_class       = "db.t2.micro"
  name                 = "exampledb"
  username             = var.db_username
  password             = random_password.db_password.result
  vpc_security_group_ids = [aws_security_group.example.id]
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.example.arn
  tags = {
