# Configure the AWS Provider
provider "aws" {
  region = var.aws_region
}

# Configure the Azure Provider
provider "azurerm" {
  features {}
  version = "3.34.0"
  subscription_id = var.azure_subscription_id
  client_id      = var.azure_client_id
  client_secret = var.azure_client_secret
  tenant_id      = var.azure_tenant_id
}

# Configure the Google Cloud Provider
provider "google" {
  project = var.gcp_project
  region  = var.gcp_region
}

# Create a VPC on AWS
resource "aws_vpc" "eks_vpc" {
  cidr_block = var.aws_vpc_cidr
  tags = {
    Name        = "eks-vpc"
    Environment = var.environment
  }
}

# Create a subnet on AWS
resource "aws_subnet" "eks_subnet" {
  cidr_block = var.aws_subnet_cidr
  vpc_id     = aws_vpc.eks_vpc.id
  availability_zone = var.aws_availability_zone
  tags = {
    Name        = "eks-subnet"
    Environment = var.environment
  }
}

# Create a security group on AWS
resource "aws_security_group" "eks_sg" {
  name        = "eks-sg"
  description = "Security group for EKS cluster"
  vpc_id      = aws_vpc.eks_vpc.id
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.allowed_cidr]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name        = "eks-sg"
    Environment = var.environment
  }
}

# Create an EKS cluster on AWS
resource "aws_eks_cluster" "eks_cluster" {
  name     = "eks-cluster"
  role_arn = aws_iam_role.eks_role.arn
  vpc_config {
    security_group_ids = [aws_security_group.eks_sg.id]
    subnet_ids         = [aws_subnet.eks_subnet.id]
  }
  depends_on = [
    aws_iam_role_policy_attachment.eks-AmazonEKSClusterPolicy,
    aws_iam_role_policy_attachment.eks-AmazonEKSVPCResourceController,
  ]
  tags = {
    Name        = "eks-cluster"
    Environment = var.environment
  }
}

# Create an IAM role for EKS on AWS
resource "aws_iam_role" "eks_role" {
  name        = "eks-role"
  description = "IAM role for EKS cluster"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      },
    ]
  })
  tags = {
    Name        = "eks-role"
    Environment = var.environment
  }
}

# Create an IAM policy attachment for EKS on AWS
resource "aws_iam_role_policy_attachment" "eks-AmazonEKSClusterPolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_role.name
}

# Create an IAM policy attachment for EKS VPC resource controller on AWS
resource "aws_iam_role_policy_attachment" "eks-AmazonEKSVPCResourceController" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.eks_role.name
}

# Create a resource group on Azure
resource "azurerm_resource_group" "aks_rg" {
  name     = "aks-rg"
  location = var.azure_location
  tags = {
    Name        = "aks-rg"
    Environment = var.environment
  }
}

# Create a virtual network on Azure
resource "azurerm_virtual_network" "aks_vnet" {
  name                = "aks-vnet"
  address_space       = [var.azure_vnet_cidr]
  location            = azurerm_resource_group.aks_rg.location
  resource_group_name = azurerm_resource_group.aks_rg.name
  tags = {
    Name        = "aks-vnet"
    Environment = var.environment
  }
}

# Create a subnet on Azure
resource "azurerm_subnet" "aks_subnet" {
  name                 = "aks-subnet"
  resource_group_name = azurerm_resource_group.aks_rg.name
  virtual_network_name = azurerm_virtual_network.aks_vnet.name
  address_prefixes     = [var.azure_subnet_cidr]
  tags = {
    Name        = "aks-subnet"
    Environment = var.environment
  }
}

# Create a security group on Azure
resource "azurerm_network_security_group" "aks_sg" {
  name                = "aks-sg"
  location            = azurerm_resource_group.aks_rg.location
  resource_group_name = azurerm_resource_group.aks_rg.name
  security_rule {
    name                       = "SSH"
    priority                   = 100
    direction                  = "Inbound"
    access                     = "Allow"
    protocol                   = "Tcp"
    source_port_range          = "*"
    destination_port_range     = "22"
    source_address_prefix      = var.allowed_cidr
    destination_address_prefix = "*"
  }
  tags = {
    Name        = "aks-sg"
    Environment = var.environment
  }
}

# Create an AKS cluster on Azure
resource "azurerm_kubernetes_cluster" "aks_cluster" {
  name                = "aks-cluster"
  location            = azurerm_resource_group.aks_rg.location
  resource_group_name = azurerm_resource_group.aks_rg.name
  dns_prefix          = "aks-dns"
  kubernetes_version = var.azure_kubernetes_version
  default_node_pool {
    name       = "aks-nodepool"
    node_count = var.azure_node_count
    vm_size    = var.azure_vm_size
  }
  network_profile {
    network_plugin = "azure"
    load_balancer_sku = "standard"
  }
  identity {
    type = "SystemAssigned"
  }
  tags = {
    Name        = "aks-cluster"
    Environment = var.environment
  }
}

# Create a network on GCP
resource "google_compute_network" "gke_network" {
  name                    = "gke-network"
  auto_create_subnetworks = false
  tags = {
    Name        = "gke-network"
    Environment = var.environment
  }
}

# Create a subnet on GCP
resource "google_compute_subnetwork" "gke_subnet" {
  name          = "gke-subnet"
  ip_cidr_range = var.gcp_subnet_cidr
  network       = google_compute_network.gke_network.id
  region        = var.gcp_region
  tags = {
    Name        = "gke-subnet"
    Environment = var.environment
  }
}

# Create a firewall rule on GCP
resource "google_compute_firewall" "gke_firewall" {
  name    = "gke-firewall"
  network = google_compute_network.gke_network.id
  allow {
    protocol = "tcp"
    ports    = ["22"]
  }
  source_ranges = [var.allowed_cidr]
  target_tags   = ["gke-node"]
  tags = {
    Name        = "gke-firewall"
    Environment = var.environment
  }
}

# Create a GKE cluster on GCP
resource "google_container_cluster" "gke_cluster" {
  name               = "gke-cluster"
  location           = var.gcp_region
  project            = var.gcp_project
  network            = google_compute_network.gke_network.id
  subnetwork         = google_compute_subnetwork.gke_subnet.id
  node_pool {
    name       = "gke-nodepool"
    node_count = var.gcp_node_count
  }
  private_cluster_config {
    enable_private_nodes = true
  }
  master_auth {
    username = var.gcp_username
    password = var.gcp_password
  }
  tags = {
    Name        = "gke-cluster"
    Environment = var.environment
  }
}

