      paths   = var.gcp_paths
      service = google_compute_backend_bucket.gcp_cdn.self_link
    }
  }

  tags = {
    Environment = var.environment
    Project     = var.project
  }
}

resource "google_compute_target_https_proxy" "gcp_cdn" {
