  count = length(var.subnet_cidrs)

  vpc_id     = aws_vpc.this.id
  cidr_block = var.subnet_cidrs[count.index]
  availability_zone = "${var.region}${count.index % 3 + 1}"
  tags = {
    Name        = "${var.project}-${var.environment}-subnet-${count.index}"
