        image = var.image_url
      }
    }
  }

  traffic {
    percent         = var.traffic_percentages.latest
    latest_revision = true
  }

  traffic {
    percent = var.traffic_percentages.canary
    revision = google_cloud_run_revision.canary.name
  }

  depends_on = [google_cloud_run_revision.canary]
}

